// React 18: useTransition + useDeferredValue 保持输入响应
import { useState, useTransition, useDeferredValue, memo } from 'react';

const ResultList = memo(function ResultList({ query }) {
  // 只在 deferredQuery 真正变化时重渲染
  const items = useSearchResults(query);
  return (
    <ul>
      {items.map(item => <li key={item.id}>{item.title}</li>)}
    </ul>
  );
});

function SearchPage() {
  const [query, setQuery] = useState('');
  const [isPending, startTransition] = useTransition();
  const deferredQuery = useDeferredValue(query);
  const isStale = query !== deferredQuery;

  return (
    <section>
      <input
        value={query}
        onChange={e => {
          setQuery(e.target.value); // 同步更新输入值，保证输入响应
          // 搜索结果的更新不阻塞输入
        }}
      />
      <div style={{ opacity: isStale ? 0.6 : 1 }}>
        {isPending && <span>Searching...</span>}
        <ResultList query={deferredQuery} />
      </div>
    </section>
  );
}

// React 19: useActionState 统一表单提交状态
import { useActionState } from 'react';

async function updateProfile(prevState, formData) {
  const name = formData.get('name');
  if (!name || name.length < 2) {
    return { error: 'Name must be at least 2 characters', savedName: prevState.savedName };
  }
  const result = await fetch('/api/profile', {
    method: 'POST',
    body: JSON.stringify({ name }),
  });
  if (!result.ok) return { error: 'Server error', savedName: prevState.savedName };
  return { error: null, savedName: name };
}

function ProfileForm() {
  const [state, formAction, isPending] = useActionState(updateProfile, {
    error: null,
    savedName: '',
  });
  return (
    <form action={formAction}>
      <input name="name" />
      <button type="submit" disabled={isPending}>
        {isPending ? 'Saving...' : 'Save'}
      </button>
      {state.error && <p role="alert">{state.error}</p>}
      {state.savedName && <p>Saved: {state.savedName}</p>}
    </form>
  );
}

// React 19: useOptimistic 乐观更新
import { useOptimistic } from 'react';

function CommentSection({ comments, addComment }) {
  const [optimisticComments, addOptimistic] = useOptimistic(
    comments,
    (currentComments, newText) => [
      ...currentComments,
      { id: `temp-${Date.now()}`, text: newText, sending: true },
    ]
  );

  async function submitAction(formData) {
    const text = formData.get('comment');
    addOptimistic(text); // 立即展示
    await addComment(text); // 失败时 React 自动回滚
  }

  return (
    <form action={submitAction}>
      <input name="comment" />
      <button>Post</button>
      <ul>
        {optimisticComments.map(c => (
          <li key={c.id} style={{ opacity: c.sending ? 0.5 : 1 }}>
            {c.text}
          </li>
        ))}
      </ul>
    </form>
  );
}
